llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The closest analogue, estradiol, has an absolute oral bioavailability of approximately 5% in humans after a 4 mg oral dose, reflecting extensive first-pass metabolism; the query is its 17β-cyclopentylpropionate ester and shares the same estradiol core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Testosterone undecanoate, a lipophilic steroid ester prodrug analogous to the query's ester modification, has a mean absolute oral bioavailability of only 6.8 ± 3.3% in humans, showing that esterification does not overcome low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "2-Methoxyestradiol, another estradiol derivative, has oral bioavailability of only 1–2% in patients, supporting low systemic availability for estradiol-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Fulvestrant, a highly lipophilic estradiol derivative, has poor oral bioavailability and requires intramuscular injection, consistent with low F for very lipophilic estradiol analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ethinyl estradiol has higher absolute bioavailability (~49%) in humans, but this is attributable to the 17α-ethinyl group that blocks first-pass metabolism; the query lacks this protective group, so this high-F evidence is less transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Estetrol is reported to have high oral bioavailability, but its polyhydroxylated structure and distinct metabolic profile make it a poor model for the lipophilic ester query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Moxestrol has 35% absolute oral bioavailability, but it contains 11β-methoxy and ethinyl modifications that reduce metabolism; the query lacks these, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low oral bioavailability (F < 20%). The query is estradiol cypionate, a 17β-ester prodrug of estradiol. The closest analogue estradiol has absolute oral bioavailability of ~5% in humans, and analogous lipophilic steroid ester prodrugs such as testosterone undecanoate also show F < 10%. High-bioavailability analogues (ethinyl estradiol, estetrol, moxestrol) owe their improved F to metabolic-protecting modifications absent in the query. Therefore, low is the best-supported prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability data for estradiol cypionate itself; extrapolation relies on estradiol and steroid ester prodrugs.",
    "Potential lymphatic absorption or formulation effects of the cyclopentylpropionate ester are not directly quantified.",
    "The very high lipophilicity and poor solubility may further reduce oral absorption, but this is not directly measured in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

